  ["541ff4b950a83bae"] = { "Ulbrek Firehand prende molto sul serio la cura degli animali. Di solito sta con i cacciatori nella Hall of Arms, se vuoi che si occupi di un famiglio o due.", "." },
  ["5423314c870a53b7"] = { "Mmm, mmm, mmm. Senti che profumino?! Questa sì che è roba buona, {class}. L'⟦Rainbow Fin Albacore=Alborella Iridata in Carpione⟧ colpisce nel segno ogni volta. Qui c'è Slicky Gastronome, asso indiscusso di tutto ciò che è commestibile, soprattutto il pesce. Con la guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧ alle porte, l'⟦Alliance=Alleanza⟧ ha pensato bene di chiamare un esperto per lo sforzo bellico, ed eccomi qui, a comandare in grande.\n\nSembra che ci serviranno $2093w di questi pesci, e per ora ne abbiamo un mucchio che arriva a $2092w.", "." },
  ["5428173d5c3f29e8"] = { "%s ruggisce verso Terenthis in segno d'intesa.", "." },
  ["54302a90e5862f38"] = { "Nessuno sfida i nomadi Wastewander... nemmeno i polli robotici! ALL'ATTACCO!", "." },
  ["5433e25c11890db6"] = { "Sospettiamo che, per conservare la loro fortuna e il loro dominio sulla terra, ben oltre la durata della loro vita, i Barov abbiano stretto un patto con un potente mago umano di nome Kel'Thuzad.\n\n<Eva rabbrividisce.>\n\nDa quel patto nacque la scuola di negromanzia: un luogo che diede vita al Cult of the Damned e che sarebbe diventato la sua capitale.\n\nCon il passare delle settimane, la casata Barov divenne sempre più decrepita...\n\nEsseri oscuri cominciarono a stabilirsi nelle varie ali della casa. La manutenzione divenne impossibile... e disgustosa.", "." },
  ["54344ef2cca8a1f5"] = { "L'Abyssal Council non tollera l'inganno! Senti la nostra ira, <piccolo/piccola> {race}!", "." },
  ["54347f35fea83f19"] = { "⟦Tower Point=Torre Granguardia⟧ è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ la distruggerà!", "." },
  ["5456b59aef3be5f0"] = { "C'è dell'altro?", "." },
  ["545b411e79de6056"] = { "Non puoi nasconderti da me!", "." },
  ["546dd6cb0dae420d"] = { "L'orso ti guarda con calma e pazienza, ma non dice nulla.", "." },
  ["547414273202a272"] = { "Vogliamo affrontare il Profanatore.", "." },
  ["5475eaabd126ccac"] = { "Davvero? Chiamali, servitore.", "." },
  ["547ad6651b4db0be"] = { "Le tue capacità superano le mie competenze. Georgio Bolero, il maestro di Duncan's Textiles qui dietro l'angolo, potrebbe aiutarti a migliorare le tue abilità.", "." },
  ["54805afa085bc7f7"] = { "Ci siamo, {name}. La mia roba dovrebbe essere in quella stanza. Coprimi, entro!", "." },
  ["5486f890fa35a178"] = { "<Lady Sylvanas Windrunner ti osserva in silenzio.>", "." },
  ["54875ae89acbe73d"] = { "Non sai quello che fai! Dobbiamo distruggerti per il tuo stesso bene.", "." },
  ["548b8baaaeb03352"] = { "Ah ah! Ho Betsy!", "." },
  ["549a9eac32159f92"] = { "Portate quei pezzi giù alla nave!", "." },
  ["549eafc05f511874"] = { "Il nostro capo, Doom'rel, è disposto ad ascoltare la sfida.", "." },
  ["54a9727e39d5b13e"] = { "Sì, be'... andiamo al monumento dedicato agli eroi delle due Grandi Guerre, la ⟦Valley of Heroes=Valle degli Eroi⟧. Seguimi.", "." },
  ["54afeb0b128ae3fb"] = { "Ti insegnerò ad abbattere i tuoi nemici come alberelli nella foresta.", "." },
  ["54b25c84541eef52"] = { "%s scruta chi è venuto a visitare l'accampamento.", "." },
  ["54bdbc2a595505f7"] = { "Attorno alla tua carcassa nascerà un nuovo mestiere, {name}. Lo chiameremo 'lavorazione della carne'.", "." },
  ["54be767168906108"] = { "Insegnante, ci sono elfi della notte a ⟦Stormwind=Roccavento⟧? Non ho mai visto un elfo della notte.", "." },
  ["54c7b13f8fef27db"] = { "%s sbadiglia.", "." },
  ["54cde6562e415ab2"] = { "Sì, giovane, non devi convincermi di cose simili: io e il Capoguerra abbiamo molta storia in comune. La tua dedizione, però, non passa inosservata.\n\nCome stavo dicendo, Rend aveva trovato una nuova casa per il suo popolo, e io fui tra quelli che lo seguirono stancamente.\n\nDa un conflitto ne nacquero altri... innumerevoli altri. Fu in quelle battaglie per i ⟦Blackrock Spire=Bastioni di Roccianera⟧ tra il clan ⟦Blackrock=Roccianera⟧ e i nani ⟦Dark Iron=Ferroscuro⟧ che entrambi i miei figli furono uccisi. Fu allora che capii che il mio tempo nel clan ⟦Blackrock=Roccianera⟧ era giunto al termine.", "." },
  ["54d5dc9eb0d75a97"] = { "Renditi utile e dammi una mano qui!", "." },
