  ["54e373b88a8e9fc5"] = { "L'⟦Alliance=Alleanza⟧ ha preso la miniera!", "." },
  ["54e625a461c246da"] = { "I tuoi dischi ti saranno restituiti quando accederai al piedistallo.", "." },
  ["54fbe825a7169532"] = { "Soldati di Kalimdor! Eroi di ⟦Silithus=Silitus⟧! Uno di voi ha inferto un colpo feroce ai nostri nemici mortali! {name} e i suoi alleati hanno liberato le ⟦Ruins of Ahn'Qiraj=Rovine di Ahn'qiraj⟧ dal loro spietato capo! Ossirian the Unscarred, flagello di ⟦Silithus=Silitus⟧, è stato finalmente distrutto e i suoi eserciti completamente smantellati!", "." },
